  (forall st1 LS1 mo c1 n1, AMPOST st LS st1 LS1 mo (c1 - c) (Z.of_nat n1 - Z.of_nat n) -> apw ecost (k st1 mo) c1 n1 Q) ->
  apw ecost (alloc_meta st k bail) c n Q.
